{"command":"cd /tmp/opencode && python3 - <<'EOF'
from pathlib import Path
from cryptography.hazmat.primitives.ciphers.aead import AESGCM
v=Path('/var/lib/vaultctl')
catalog=__import__('json').loads((v/'catalog.json').read_text())
keys={p.stem:p.read_bytes() for p in sorted((v/'keys').glob('*.key'))}
print('key files (bytes):', {k:len(m) for k,m in keys.items()})
print('recovery store:', sorted(p.name for p in (v/'recovery').iterdir()) or 'EMPTY')
consumers={k:[] for k in keys}
for aid,e in catalog.items():
    blob=(v/'archives'/(aid+'.bin')).read_bytes()
    print(f"{aid}: catalog key_id={e['key_id']}")
    for k,mat in keys.items():
        try:
            AESGCM(mat).decrypt(blob[:12],blob[12:],k.encode())
            consumers[k].append(aid); print('   ',k,'-> DECRYPTS')
        except Exception as ex: print('   ',k,'-> fail',type(ex).__name__)
print('consumers:',consumers)
EOF"}

